import { deferred, isOpen } from '../claims/claims';
import type { Claim } from '../claims/claims';

/** Whether a claim is overdue: it is OPEN (or PENDING), not deferred, and its due-by, fixed when it was created, is before the sheet's today. */
export function overdue(claim: Claim, today: string): boolean {
  return isOpen(claim) && !deferred(claim, today) && today !== '' && claim.dueBy < today;
}

/** How many full 30-day periods a claim is overdue on the sheet's today: 0 unless it is overdue. */
export function latePeriods(claim: Claim, today: string): number {
  if (!overdue(claim, today)) return 0;
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${claim.dueBy}T00:00:00Z`)) / 86_400_000;
  return Math.floor(Math.round(days) / 30);
}

/** The date the claim's nth (1, 2, ...) full 30-day overdue period ends: its due-by plus 30 × n days (yyyy-MM-dd). */
export function lateBoundary(claim: Claim, period: number): string {
  return new Date(Date.parse(`${claim.dueBy}T00:00:00Z`) + period * 30 * 86_400_000).toISOString().slice(0, 10);
}
          <th />
        </tr>
      </thead>
      <tbody>
        {(people.data ?? []).filter((p) => showRetired || !p.retired).map((p) => (
          <tr key={p.id} data-testid={`person-row-${p.id}`}>
            <td data-testid="person-name" style={{ whiteSpace: 'pre' }}>
              {p.name}
            </td>
            <td data-testid="person-grade">{p.grade}</td>
            <PersonColumns.Slot person={p} />
            <td>
              <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => setEditing(p.id)}>
                Edit
              </button>
              <PersonError personId={p.id} />
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

/**
 * A person on the sheet as the store holds them; `grade` is the one in force on the sheet's today and
 * `grades` every grade recorded for them, each from its from-date; `version` counts their saves. `statementCount` counts
 * the statements taken of them; `statedTotal` is the last one's due-total and `statementDate` the
 * sheet's today when it was taken, both null before the first. `retired` is whether a retirement date is
 * set (whatever the date), `retiredFrom` that date, null while they are not retired. `held` is whether
 * they have any hold, `holds` each hold, oldest first: their open claims dated within one, and not bound by a
 * statement, count in no live total.
 */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: GradeFrom[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
